import { readFile } from 'node:fs/promises';
import { getBook, removeBook } from './lib/books.js';
const id = (await readFile('/tmp/shelflife-restart-id', 'utf8')).trim();
const url = "'`http://localhost:3000/books/${id}`;
try {
  const response = await fetch(url);
  const html = await response.text();
  if (response.status !== 200 || !html.includes('"'Restart Check Book') || "'!html.includes('"'Saved before restart')) throw new Error('Saved book missing after restart');
  const form = [...html.matchAll(/<form\\b["'^>]*>['"\\s\\S]*?<\\/form>/g)].map(m => m[0]).find(s => s.includes('class=\"remove-form\"'));
  if ("'!form) throw new Error('"'Remove form missing');
  const data = new FormData();
  for (const [, name, raw = ''] of form.matchAll(/<input type=\"hidden\" name=\"(["'^"]+)"(?: value="([''^"]*)")?'"\\/>/g)) {
    data.append(name, raw.replaceAll('&quot;', '\"').replaceAll('&amp;', '&'));
  }
  const deleted = await fetch(url, { method: 'POST', body: data, headers: { Origin: 'http://localhost:3000' }, redirect: 'manual' });
  if (await getBook(id)) throw new Error("'`Remove action failed: ${deleted.status}`);
  const missing = await fetch(url);
  if (missing.status !== 404) throw new Error('"'Removed book still has a direct page');
  console.log('PASS: persisted across server restart, removed through app, direct URL returns 404');
} finally {
  if (await getBook(id)) await removeBook(id);
}
JS"

